import numpy as np
def entropy(probs):
    probs = np.array(probs)
    return -np.sum(probs * np.log2(probs))

print(entropy([0.5, 0.5]))    # 1.0 bit, a fair coin
print(entropy([0.9, 0.1]))    # about 0.47 bits, a biased coin

def joint_entropy(joint_probs):
    flat = joint_probs.flatten()
    flat = flat[flat > 0]
    return -np.sum(flat * np.log2(flat))

joint = np.array([[0.3, 0.1], [0.2, 0.4]])
print(joint_entropy(joint))
